/* From Uiverse.io by Tsiangana  - Tags: simple, gradient, button, download, hover effect */
.__UIV_SCOPE__ .button {
  width: 140px;
  height: 45px;
  border-radius: 30em;
  position: relative;
  overflow: hidden;
  color: #fff;
  font-family: Roboto, sans-serif;
  font-weight: 600;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
  z-index: 1;
  background: #ff135a;
  border: 3px solid #fff;
  box-shadow: 6px 6px 12px #c5c5c5, -6px -6px 12px #ffffff;
  transition: 0.6s ease-in;
}

.__UIV_SCOPE__ .button:hover {
  background: #fff;
}

.__UIV_SCOPE__ .button .two {
  display: none;
}

.__UIV_SCOPE__ .button::before {
  content: "";
  width: 0;
  height: 50px;
  border-radius: 30em;
  position: absolute;
  top: 0;
  left: 0;
  background-image: linear-gradient(to right, #0fd850 0%, #f9f047 100%);
  transition: 0.5s ease;
  display: block;
  z-index: -1;
}

.__UIV_SCOPE__ .button:hover::before {
  width: 140px;
  transition: 3s linear;
}

.__UIV_SCOPE__ .button:hover .one {
  display: none;
}

.__UIV_SCOPE__ .button:hover .two {
  display: inline;
}
